package sonar.calculator.mod.client.model;

import com.mojang.blaze3d.vertex.PoseStack;
import com.mojang.blaze3d.vertex.VertexConsumer;
import net.minecraft.client.model.geom.ModelPart;
import net.minecraft.client.model.geom.PartPose;
import net.minecraft.client.model.geom.builders.CubeListBuilder;
import net.minecraft.client.model.geom.builders.LayerDefinition;
import net.minecraft.client.model.geom.builders.MeshDefinition;
import net.minecraft.client.model.geom.builders.PartDefinition;

/** Exact Techne boxes, UV offsets and pivots from Calculator 1.12 (MIT). Generated by convert_assets_models.py. */
public final class ModelCrankHandle {
    private ModelCrankHandle() {}
    public static LayerDefinition createLayer() {
        MeshDefinition mesh = new MeshDefinition();
        PartDefinition root = mesh.getRoot();
        root.addOrReplaceChild("base", CubeListBuilder.create().texOffs(0, 14).addBox(0.0F, 0.0F, 0.0F, 2.0F, 3.0F, 2.0F), PartPose.offsetAndRotation(-1.0F, 21.0F, -1.0F, 0.0F, 0.0F, 0.0F));
        root.addOrReplaceChild("piece", CubeListBuilder.create().texOffs(0, 8).addBox(0.0F, 0.0F, 0.0F, 2.0F, 4.0F, 2.0F), PartPose.offsetAndRotation(3.0F, 15.0F, -1.0F, 0.0F, 0.0F, 0.0F));
        root.addOrReplaceChild("grasp", CubeListBuilder.create().texOffs(0, 4).addBox(0.0F, 0.0F, 0.0F, 3.0F, 1.0F, 3.0F), PartPose.offsetAndRotation(2.5F, 14.0F, -1.5F, 0.0F, 0.0F, 0.0F));
        root.addOrReplaceChild("joint", CubeListBuilder.create().texOffs(0, 0).addBox(0.0F, 0.0F, 0.0F, 6.0F, 2.0F, 2.0F), PartPose.offsetAndRotation(-1.0F, 19.0F, -1.0F, 0.0F, 0.0F, 0.0F));
        return LayerDefinition.create(mesh, 64, 32);
    }
    public static void render(ModelPart root, PoseStack poses, VertexConsumer vertices, int light, int overlay) {
        root.getChild("base").render(poses, vertices, light, overlay);
        root.getChild("piece").render(poses, vertices, light, overlay);
        root.getChild("grasp").render(poses, vertices, light, overlay);
        root.getChild("joint").render(poses, vertices, light, overlay);
    }
}
